using System.Globalization;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;

namespace Toushir.Wholesale;
public class OrderDocument(WholesaleDb db,OrderService orders) {
 public async Task<string> Html(Actor a,string id){var o=await orders.Find(a,id);var merchant=await db.Accounts.AsNoTracking().FirstAsync(x=>x.Id==o.AccountId);var workspace=await db.Workspaces.AsNoTracking().FirstAsync(x=>x.Id==a.WorkspaceId);var credits=(await db.Credits.AsNoTracking().Where(x=>x.WorkspaceId==a.WorkspaceId&&x.OrderId==o.Id).ToListAsync()).OrderBy(x=>x.At).ToList();var creditTotal=credits.Sum(x=>x.Amount);var completed=o.Status is "DELIVERED" or "PARTIALLY_DELIVERED" or "DELIVERY_REFUSED";string H(string? s)=>WebUtility.HtmlEncode(s??"");string Money(decimal? x)=>x==null?"Sur devis":x.Value.ToString("N2",CultureInfo.InvariantCulture)+" DZD";var address=OrderService.ReadAddress(o.AddressJson);string A(string name)=>address.GetValueOrDefault(name.ToLowerInvariant(),"");var title=o.Status=="CANCELLED"?"Commande annulée":o.Status is "REQUESTED"?"Demande de devis":o.Status is "QUOTED"?"Devis commercial":"Bon de commande";var sb=new StringBuilder();sb.Append("<!doctype html><html lang='fr'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>").Append(H(title+" "+o.Number)).Append("</title><style>body{font:14px system-ui,sans-serif;line-height:1.5;color:#002d2c;margin:0;background:#f2f6f3}.page{max-width:960px;margin:32px auto;padding:40px;background:white;border-radius:20px}header{display:flex;justify-content:space-between;gap:20px;border-bottom:3px solid #06dd81;padding-bottom:24px}.brand{font-size:30px;font-weight:800;letter-spacing:-1px}.muted{color:#667570}h1{font-size:25px;margin:0}h2{font-size:16px}.meta{display:flex;gap:40px;margin:24px 0}.meta>div{flex:1}table{border-collapse:collapse;width:100%;margin:24px 0}th,td{text-align:left;border-bottom:1px solid #e1e9e3;padding:12px 8px}th{background:#f2f8f4;font-size:12px}.right{text-align:right}.totals{max-width:360px;margin-left:auto}.totals p{display:flex;justify-content:space-between}.total{font-size:20px;font-weight:700;padding-top:12px;border-top:2px solid #002d2c}.notice{background:#f2f8f4;padding:16px;border-radius:12px;margin-top:24px}button{border:0;border-radius:9px;background:#002d2c;color:#fff;padding:12px 20px;cursor:pointer}@media(max-width:600px){.page{padding:20px;margin:0;border-radius:0}.meta,header{display:block}table{font-size:11px}th,td{padding:8px 4px}}@media print{body{background:white}.page{margin:0;padding:0;max-width:none}button{display:none}thead{display:table-header-group}tr{break-inside:avoid}.notice{break-inside:avoid}}</style></head><body><main class='page'><header><div><div class='brand'>toushir<span style='color:#06dd81'>.</span></div><div>").Append(H(workspace.Name)).Append("</div>");if(workspace.IsDemo)sb.Append("<div class='muted'>DÉMONSTRATION · ESPACE FICTIF</div>");sb.Append("</div><div><h1>").Append(H(title)).Append("</h1><strong>").Append(H(o.Number)).Append("</strong><div class='muted'>").Append(H(o.CreatedAt.ToOffset(TimeSpan.FromHours(1)).ToString("dd/MM/yyyy HH:mm"))).Append(" · Oran</div><div>").Append(H(o.Status)).Append("</div></div></header><section class='meta'><div><h2>Commerçant</h2><strong>").Append(H(merchant.ShopName)).Append("</strong><br>").Append(H(merchant.Name)).Append("<br>").Append(H(merchant.Phone)).Append("</div><div><h2>Adresse de livraison</h2>").Append(H(A("Street"))).Append("<br>").Append(H(A("Commune")+", "+A("Wilaya"))).Append("</div></section>").Append(o.Status=="CANCELLED"?"<div class='notice'>Commande annulée : aucun montant contractuel ne reste dû. Les lignes ci-dessous conservent les conditions initiales pour l’historique. Un encaissement antérieur reste visible et son remboursement doit être enregistré séparément.</div>":"").Append("<table><thead><tr><th>Produit</th><th>Qté demandée</th><th>Qté retenue</th><th class='right'>Prix unitaire</th><th class='right'>Montant</th></tr></thead><tbody>");foreach(var l in o.Items){sb.Append("<tr><td><strong>").Append(H(l.Name)).Append("</strong><br><span class='muted'>").Append(H(l.Brand)).Append("</span></td><td>").Append(l.RequestedQuantity).Append("</td><td>").Append(o.QuoteVersion==0&&o.Status=="REQUESTED"?"À confirmer":(completed?l.AcceptedQuantity:l.Quantity).ToString()).Append("</td><td class='right'>").Append(H(Money(l.UnitPrice))).Append("</td><td class='right'>").Append(H(Money(completed?l.UnitPrice*l.AcceptedQuantity:l.LineTotal))).Append("</td></tr>");}sb.Append("</tbody></table><div class='totals'><p><span>Sous-total</span><span>").Append(H(Money(o.Subtotal+creditTotal))).Append("</span></p>").Append(creditTotal>0?"<p><span>Avoirs commerciaux</span><span>−"+H(Money(creditTotal))+"</span></p>":"").Append("<p><span>Livraison</span><span>").Append(H(Money(o.DeliveryFee))).Append("</span></p><p class='total'><span>Total</span><span>").Append(H(Money(o.Total))).Append("</span></p><p><span>Encaissé net</span><span>").Append(H(Money(o.Collected))).Append("</span></p>").Append(o.Total!=null&&o.Collected>o.Total?"<p><span>À rembourser</span><span>"+H(Money(o.Collected-o.Total))+"</span></p>":"").Append("</div>");if(credits.Count>0){sb.Append("<h2>Avoirs commerciaux</h2><ul>");foreach(var credit in credits)sb.Append("<li>").Append(H(credit.Id[..12]+" · "+Money(credit.Amount)+" · "+credit.Reason)).Append("</li>");sb.Append("</ul>");}if(o.QuoteValidUntil!=null)sb.Append("<p>Devis version ").Append(o.QuoteVersion).Append(" · Validité : ").Append(H(o.QuoteValidUntil.Value.ToOffset(TimeSpan.FromHours(1)).ToString("dd/MM/yyyy HH:mm"))).Append(" (Algérie).</p>");if(o.Note.Length>0)sb.Append("<h2>Note du commerçant</h2><p>").Append(H(o.Note)).Append("</p>");if(o.AdminNote.Length>0)sb.Append("<h2>Note du grossiste</h2><p>").Append(H(o.AdminNote)).Append("</p>");sb.Append("<div class='notice'>Document commercial de suivi, à conserver avec votre commande. Ce document n'est pas une facture fiscale. Les prix et disponibilités n'engagent le grossiste qu'après devis valide et acceptation. Les données du catalogue ouvert ne constituent pas un tarif grossiste.</div><p><button onclick='window.print()'>Imprimer / Enregistrer en PDF</button></p></main></body></html>");return sb.ToString();}
